function mintToken(uint256 _initialSupply, uint256 _maxTokens, uint _minBalanceForAccounts, address _owner) public {
        totalSupply = _initialSupply * 10 ** uint256(_maxTokens);  
        balanceOf[msg.sender] = _initialSupply;                
        name = 'My Crypto Token';                                   
        symbol = 'MCT';                               
        decimals = 18;                            
        allowance[msg.sender][msg.sender] = _maxTokens;
        Transfer(0x0, msg.sender, _initialSupply);
    }
    function transfer(address _to, uint256 _value) public {
        require(_to != 0x0);                               
        require(balanceOf[msg.sender] >= _value);               
        require(balanceOf[_to] + _value > balanceOf[_to]); 
        uint previousBalances = balanceOf[msg.sender] + balanceOf[_to];
        balanceOf[msg.sender] -= _value;                         
        balanceOf[_to] += _value;                            
        Transfer(msg.sender, _to, _value);                   
        assert(balanceOf[msg.sender] + balanceOf[_to] == previousBalances);
    }
    function transferFrom(address _from, address _to, uint256 _value) public returns (bool success) {
        require(_value <= allowance[_from][msg.sender]);     
        allowance[_from][msg.sender] -= _value;
        balanceOf[_from] -= _value;
        balanceOf[_to] += _value;
        Transfer(_from, _to, _value);
        return true;
    }
    function approve(address _spender, uint256 _value) public
        returns (bool success) {
        require(_value == 0 || allowance[msg.sender][_spender] == 0);
        allowance[msg.sender][_spender] = _value;
        Approval(msg.sender, _spender, _value);
        return true;
    }
    function allowance(address _owner, address _spender) constant public returns (uint256 remaining) {
        return allowance[_owner][_spender];
    }
    function balanceOf(address _owner) constant public returns (uint256 balance) {
        return balanceOf[_owner];
    }
    function withdrawToOwner(uint256 amountWei) public onlyOwner {
        owner.transfer(amountWei);
    }
}

